/**
 * Gemini's identity on the key faces: a violet-blue accent and a generic
 * mark (a plain four-pointed sparkle in the accent colour, not Google's
 * logo) drawn with canvas primitives; no logo file. Owned by the architect:
 * implementers do not edit this file.
 */
import type { Brand, KeyMark } from '../types';

const ACCENT = '#8f8cf6';

const geminiMark: KeyMark = {
  draw(ctx, x, y, size) {
    const cx = x + size / 2;
    const cy = y + size / 2;
    const r = size * 0.47;
    // control points pulled slightly outwards give the sparkle full sides
    const k = r * 0.24;
    ctx.fillStyle = ACCENT;
    ctx.beginPath();
    ctx.moveTo(cx, cy - r);
    ctx.quadraticCurveTo(cx + k, cy - k, cx + r, cy);
    ctx.quadraticCurveTo(cx + k, cy + k, cx, cy + r);
    ctx.quadraticCurveTo(cx - k, cy + k, cx - r, cy);
    ctx.quadraticCurveTo(cx - k, cy - k, cx, cy - r);
    ctx.closePath();
    ctx.fill();
  },
};

export const GEMINI_BRAND: Brand = {
  name: 'Gemini',
  productName: 'Gemini CLI',
  accent: ACCENT,
  mark: geminiMark,
};
